import {DOMAINS,QUESTIONS,OPTIONS,STAGES,VERSION,validAnswers,scoreAnswers,resultIntro} from './quiz.js';
import {verifyCode,HOUR} from './access.js';
import {isSoundMuted,setSoundMuted,playSelectionSound} from './sound.js';

const $=(selector,root=document)=>root.querySelector(selector);
const app=$('#app'),gate=$('#gate'),about=$('#about'),share=$('#share'),confirmDialog=$('#confirm');
const STORE='little-strengths:answers:v1',AUTH='little-strengths:access:v1';
const esc=v=>String(v).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const flower=(cls='')=>`<svg class="flower ${cls}" aria-hidden="true"><use href="#daisy"/></svg>`;
const icon=()=>'<svg class="icon" aria-hidden="true"><use href="#arrow"/></svg>';
const animal=(n,cls='')=>`<span class="animal animal-${n} ${cls}" aria-hidden="true"></span>`;
let storageAvailable=true,state={stage:'university',answers:Array(QUESTIONS.length).fill(null),index:0,finished:false},view='home',toastTimeout,failedAttempts=0,lockedUntil=0,shareBlob=null,shareUrl=null,tagSelection=[];
try{const saved=JSON.parse(localStorage.getItem(STORE));if(saved?.version===VERSION&&validAnswers(saved.answers)&&Object.hasOwn(STAGES,saved.stage)){state={stage:saved.stage,answers:saved.answers,index:Number.isInteger(saved.index)?Math.max(0,Math.min(QUESTIONS.length-1,saved.index)):0,finished:!!saved.finished&&saved.answers.every(v=>v!==null)};}}catch{storageAvailable=false;}
function persist(){try{localStorage.setItem(STORE,JSON.stringify({...state,version:VERSION}));}catch{storageAvailable=false;}}
function hasAccess(){try{const stamp=Number(sessionStorage.getItem(AUTH));return Number.isFinite(stamp)&&stamp>0&&Date.now()-stamp>=0&&Date.now()-stamp<12*HOUR;}catch{return gate.dataset.verified==='true';}}
function toast(message){clearTimeout(toastTimeout);$('#toast').textContent=message;$('#toast').classList.add('visible');toastTimeout=setTimeout(()=>$('#toast').classList.remove('visible'),2800);}
function header(extra=''){return `<header class="topbar"><button class="wordmark" data-action="home" aria-label="回到小册首页">${flower()}日常优势小册</button>${extra||'<button class="icon-button" data-action="about" aria-label="关于这份自评">?</button>'}</header>`;}
function navigate(next,{replace=false}={}){view=next;const hash=next==='home'?'#start':next==='quiz'?'#question':'#result';if(location.hash!==hash)history[replace?'replaceState':'pushState'](null,'',hash);render();window.scrollTo({top:0,behavior:'instant'});requestAnimationFrame(()=>$('.screen h1',app)?.focus({preventScroll:true}));}
function render(){if(view!=='home'&&!hasAccess()){view='home';history.replaceState(null,'','#start');}if(view==='result'&&!state.finished)view='home';document.body.classList.toggle('quiz-active',view==='quiz');app.classList.toggle('quiz-notebook',view==='quiz');if(view==='home')renderHome();else if(view==='quiz')renderQuestion();else renderResult();}
function renderHome(){const resume=state.answers.some(v=>v!==null);app.innerHTML=`<section class="screen home-screen">${header()}<h1 class="home-heading" tabindex="-1">我的优势，<br>藏在哪些<span class="title-mark">小事里</span>？</h1><p class="home-deck">在平常日子里，认出自己的闪光。</p><div class="cover-scene" aria-hidden="true"><div class="meadow"></div>${animal(0,'cover-main')}${animal(1,'cover-left')}${animal(2,'cover-right')}${flower('scene-flower')}${flower('scene-flower left')}<svg class="spark"><use href="#spark"/></svg><svg class="spark left"><use href="#spark"/></svg><div class="small-grass"></div></div><div class="cover-meta"><span>${QUESTIONS.length} 件日常小事</span><i class="meta-dot"></i><span>约 4 分钟</span><i class="meta-dot"></i><span>原创自评</span></div><div class="stage-row"><span class="stage-label" id="stage-label">现在的我</span><div class="stage-group" role="radiogroup" aria-labelledby="stage-label">${Object.entries(STAGES).map(([id,label])=>`<label class="stage-option"><input type="radio" name="stage" value="${id}" ${state.stage===id?'checked':''}><span>${label}</span></label>`).join('')}</div></div><button class="primary" data-action="begin">${state.finished?'翻开我的结果':resume?'继续我的小册':'发现我的优势'}${icon()}</button>${!storageAvailable?'<p class="storage-note" role="status">当前浏览器无法保存进度，请在本次访问中完成。</p>':''}<footer class="home-foot"><button class="quiet" data-action="about">关于这份自评</button>${resume?'<button class="quiet" data-action="restart">重新开始</button>':''}</footer><p class="edition">记录平凡，也看见自己</p></section>`;}
function soundButton(){return `<button class="sound-button" data-action="sound" aria-label="${isSoundMuted()?'开启选择音效':'关闭选择音效'}" aria-pressed="${!isSoundMuted()}" title="${isSoundMuted()?'开启选择音效':'关闭选择音效'}"><svg viewBox="0 0 24 24" aria-hidden="true"><path d="M11 5 6 9H3v6h3l5 4Z"/><path class="sound-waves" d="M15 8a6 6 0 0 1 0 8m3-11a10 10 0 0 1 0 14"/><path class="sound-cross" d="m15 9 6 6m0-6-6 6"/></svg></button>`;}
let lastAnswerTap=null,lastAutoConfirmAt=-Infinity;
function renderQuestion(){lastAnswerTap=null;const q=QUESTIONS[state.index],value=state.answers[state.index];const companion=Math.floor(state.index/4)%DOMAINS.length;app.innerHTML=`<section class="screen question-screen">${header(`<div class="question-tools">${soundButton()}<span class="counter" aria-label="第${state.index+1}题，共${QUESTIONS.length}题"><strong>${String(state.index+1).padStart(2,'0')}</strong><span> / ${QUESTIONS.length}</span></span></div>`)}<div class="progress-track" role="progressbar" aria-valuemin="0" aria-valuemax="${QUESTIONS.length}" aria-valuenow="${state.answers.filter(v=>v!==null).length}" aria-label="答题进度"><div class="progress-ink" style="width:${state.answers.filter(v=>v!==null).length/QUESTIONS.length*100}%"></div></div><div class="question-paper">${animal(companion)}<p class="question-period">最近一个月的我</p><h1 class="question-title" id="question-title" tabindex="-1">${esc(q.text)}</h1></div><fieldset class="answers" aria-labelledby="question-title" aria-describedby="answer-help"><legend class="sr-only">符合程度</legend>${OPTIONS.map((label,i)=>`<label class="answer ${value===i+1?'is-selected':''}"><input type="radio" name="answer" value="${i+1}" ${value===i+1?'checked':''}><span class="radio-drawn" aria-hidden="true"></span><span class="answer-text">${label}</span></label>`).join('')}</fieldset><div class="question-nav"><button class="back-question" data-action="previous" aria-label="${state.index===0?'回到首页':'上一题'}">${icon()}</button><button class="primary" data-action="next" ${value===null?'disabled':''}>${state.index===QUESTIONS.length-1?'看看我的优势':'下一件小事'}${icon()}</button></div><p class="question-bottom" id="answer-help">单击选择 · 双击确认并继续</p></section>`;}
function getResult(){return scoreAnswers(state.answers);}
function renderResult(){const result=getResult(),d=DOMAINS.find(d=>d.id===result.top.id);const title=result.low?'继续探索的你':result.tied.length===DOMAINS.length?'有许多面的你':d.companion;const line=result.low?'从一件小事开始，慢慢认识自己':result.tied.length===DOMAINS.length?'每个方向，都可以再走近一点':d.title;app.innerHTML=`<section class="screen result-screen">${header('<button class="quiet" data-action="share">分享卡</button>')}<div class="result-kicker">我的日常优势画像</div><article class="keepsake" style="--domain-color:${d.color};--domain-paper:${d.paper}" aria-label="优势结果卡"><div class="keepsake-top"><span>日常优势小册</span><span>${new Intl.DateTimeFormat('zh-CN',{timeZone:'Asia/Shanghai',year:'numeric',month:'2-digit',day:'2-digit'}).format(new Date()).replaceAll('/','.')}</span></div><div class="card-animal-wrap"><div class="card-blob"></div>${animal(d.animal)}${flower()}</div><p class="result-label">${result.low?'还在发现自己的路上':result.tied.length>1?'我的优势，有不止一种模样':'藏在小事里的这一面'}</p><h1 class="result-title" tabindex="-1">${esc(title)}</h1><p class="result-line">${esc(line)}</p><div class="tags">${(result.low||result.tied.length===DOMAINS.length?['保持探索','留意日常','允许变化']:d.tags).map(t=>`<span class="tag">${t}</span>`).join('')}</div><div class="card-bottom"><span class="card-bottom-label">我的优势，<br>藏在哪些小事里？</span><span class="card-bottom-meta">日常行为自评<br>${QUESTIONS.length} 题</span><img class="entry-qr" src="./assets/entry-qr.svg" alt="测评介绍页二维码"></div></article><div class="result-actions"><button class="primary" data-action="share">保存我的优势卡${icon()}</button><button class="secondary" data-action="read-report">读一读</button></div><section class="report-section" id="report"><h2 class="section-heading">${flower()}从这些小事里，看见你</h2><p>${esc(resultIntro(result,d))}</p>${!result.low?`<p>${esc(d.scenes[state.stage])}</p>`:''}${result.uniform?'<p><small>这次所有题目的选项相同，其中包含反向计分的题目。可以结合具体经历，检查这些选择是否贴近自己。</small></p>':''}</section><section class="report-section"><h2 class="section-heading">你的六种日常倾向</h2><div class="score-list">${result.scores.map(s=>{const domain=DOMAINS.find(d=>d.id===s.id);return `<div class="score-row"><span>${domain.name}</span><div class="score-track" role="meter" aria-label="${domain.name}" aria-valuemin="1" aria-valuemax="5" aria-valuenow="${s.mean}" aria-valuetext="自评 ${s.mean.toFixed(2)}，满分5"><div class="score-fill" style="width:${(s.mean-1)/4*100}%;--bar-color:${domain.color}"></div></div><span class="score-value">${s.mean.toFixed(2)}</span></div>`}).join('')}</div><small>1—5 分的自评倾向；动物形象为视觉比喻。</small></section><section class="report-section"><h2 class="section-heading">每一种优势，都有自己的用法</h2>${result.ranked.map((s,i)=>{const domain=DOMAINS.find(d=>d.id===s.id);return `<details class="detail-item" ${i===0?'open':''}><summary>${animal(domain.animal)}${domain.name}<span class="sr-only">，展开解读</span></summary><div class="detail-body"><p>${esc(domain.strength)}</p><p><span class="small-label">生活中的样子</span>${esc(domain.scenes[state.stage])}</p><p class="consider"><span class="small-label">也给自己一点余地</span>${esc(domain.balance)}</p></div></details>`}).join('')}</section><section class="report-section"><h2 class="section-heading">这周，可以试的一件小事</h2><div class="action-note">${esc(result.low?'选一件最近完成的小事，记下你做了什么、用了什么办法，以及当时有什么感受。过几天再看看，哪些行为是你愿意继续尝试的。':d.action)}</div></section><footer class="report-footer"><button class="quiet" data-action="about">依据与计分</button><button class="quiet" data-action="restart">再认识自己一次</button><button class="quiet" data-action="clear">清除记录</button></footer><p class="edition">每个人，都有慢慢生长的部分</p></section>`;}
function showAbout(){about.innerHTML=`<div class="dialog-head"><h2 class="dialog-title" id="about-title">关于这份自评</h2><button class="close-button" data-close="about" aria-label="关闭">×</button></div><div class="about-copy"><p>「我的优势，藏在哪些小事里？」是一份原创的日常行为探索问卷。24 个描述，围绕观察、创想、关照、联结、落实与复原六个方向。</p><h3>它能告诉你什么</h3><p>结果整理你对最近一个月行为的自我描述，提供反思线索与日常建议。它尚未经过信度、效度或年龄常模验证，不用于心理诊断、能力鉴定、升学或招聘判断。高中阶段同样属于探索性使用。</p><h3>如何计分</h3><p>每个选项对应 1—5 分，每个方向 4 题，其中 1 题反向计分（6 减去选项分值）。四题平均值即该方向的自评分。图中的分数不是人群排名。</p><p>结果卡展示本次相对靠前的方向；并列得分会在正文说明，默认图案按固定顺序选取，不代表该方向更重要。六项同分或最高分低于 3 时，使用探索型结果。动物仅为视觉比喻。</p><h3>题目依据与版本</h3><p>题目由本项目原创，采用具体行为、自我报告与分维度反馈的设计方式；未直接复制或声称采用任何标准量表。版本：${VERSION}。</p><p>设计参考：<a href="https://www.testingstandards.net/open-access-files.html" target="_blank" rel="noopener noreferrer">教育与心理测验标准</a>关于用途、证据与解释边界的原则。</p><h3>你的记录</h3><p>答案与结果只保存在当前浏览器，不上传。本页没有广告与第三方统计。分享图片在本地生成，只有你主动分享时才会发出。共享设备上可以在结果页清除记录。</p></div>`;about.showModal();}
async function begin(){if(hasAccess()){navigate(state.finished?'result':'quiz');return;}gate.innerHTML=`<div class="dialog-head"><h2 class="dialog-title" id="gate-title">打开你的小册</h2><button class="close-button" data-close="gate" aria-label="关闭">×</button></div><div class="gate-art">${animal(5)}</div><form id="gate-form"><label class="code-label" for="access-code">本小时口令</label><input class="code-input" id="access-code" name="code" type="text" inputmode="numeric" pattern="[0-9]{6}" autocomplete="one-time-code" maxlength="6" required aria-describedby="gate-error"><p id="gate-error" class="gate-error" role="status"></p><button class="primary gate-submit" type="submit">打开小册${icon()}</button></form>`;gate.showModal();setTimeout(()=>$('#access-code').focus(),100);}
async function submitCode(event){event.preventDefault();const input=$('#access-code'),error=$('#gate-error'),button=$('#gate-form button');input.value=input.value.replace(/\D/g,'').slice(0,6);if(input.value.length!==6){error.textContent='口令为六位数字。';return;}if(Date.now()<lockedUntil){error.textContent='尝试较多，请稍后再试。';return;}button.disabled=true;try{const pass=await verifyCode(input.value);if(!pass){failedAttempts++;if(failedAttempts>=5){lockedUntil=Date.now()+30000;failedAttempts=0;}error.textContent='口令不正确或已过期。';input.setAttribute('aria-invalid','true');input.select();return;}failedAttempts=0;gate.dataset.verified='true';try{sessionStorage.setItem(AUTH,String(Date.now()));}catch{}gate.close();navigate(state.finished?'result':'quiz');}catch{error.textContent='当前浏览器无法验证口令，请使用新版浏览器打开。';}finally{button.disabled=false;}}
function confirmAction(title,copy,label,action){confirmDialog.innerHTML=`<div class="dialog-head"><h2 class="dialog-title" id="confirm-title">${title}</h2><button class="close-button" data-close="confirm" aria-label="关闭">×</button></div><p class="confirm-copy">${copy}</p><div class="confirm-actions"><button class="secondary" data-close="confirm">保留</button><button class="primary" id="confirm-yes">${label}</button></div>`;$('#confirm-yes').onclick=()=>{confirmDialog.close();action();};confirmDialog.showModal();}
function reset(){state.answers=Array(QUESTIONS.length).fill(null);state.index=0;state.finished=false;persist();navigate('home');}
document.addEventListener('change',event=>{const el=event.target;if(el.name==='stage'&&Object.hasOwn(STAGES,el.value)){state.stage=el.value;persist();}if(el.name==='answer'){const value=Number(el.value);if(value>=1&&value<=5){playSelectionSound();state.answers[state.index]=value;state.finished=false;persist();document.querySelectorAll('.answer').forEach(label=>label.classList.toggle('is-selected',$('input',label).checked));$('[data-action="next"]').disabled=false;}}});
document.addEventListener('input',event=>{if(event.target.id==='access-code'){event.target.value=event.target.value.replace(/\D/g,'').slice(0,6);event.target.removeAttribute('aria-invalid');$('#gate-error').textContent='';}});
document.addEventListener('submit',event=>{if(event.target.id==='gate-form')submitCode(event);});

// Both the Next button and option confirmation use this exact navigation path.
function advanceQuestion(){if(state.answers[state.index]===null)return;if(state.index<QUESTIONS.length-1){state.index++;persist();renderQuestion();window.scrollTo({top:0,behavior:'instant'});$('#question-title').focus({preventScroll:true});}else{const missing=state.answers.findIndex(v=>v===null);if(missing!==-1){state.index=missing;persist();renderQuestion();return;}state.finished=true;persist();navigate('result');}}
function confirmOption(option){
  if(view!=='quiz'||!app.contains(option)||performance.now()-lastAutoConfirmAt<500)return;
  const input=$('input[name="answer"]',option),value=Number(input?.value),index=state.index;
  if(!Number.isInteger(value)||value<1||value>5)return;
  if(state.answers[index]!==value)playSelectionSound();
  state.answers[index]=value;state.finished=false;persist();
  lastAnswerTap=null;lastAutoConfirmAt=performance.now();
  // Let the second pointer/click finish before replacing the option under it.
  setTimeout(()=>{if(view==='quiz'&&state.index===index)advanceQuestion();},0);
}
let answerPointer=null;
document.addEventListener('pointerdown',event=>{
  if(event.pointerType!=='touch'&&event.pointerType!=='pen')return;
  if(!event.isPrimary){answerPointer=null;lastAnswerTap=null;return;}
  const option=event.target.closest('.answer');
  answerPointer=option&&view==='quiz'?{id:event.pointerId,option,x:event.clientX,y:event.clientY}:null;
});
document.addEventListener('pointercancel',()=>{answerPointer=null;lastAnswerTap=null;});
document.addEventListener('pointerup',event=>{
  if(event.pointerType!=='touch'&&event.pointerType!=='pen')return;
  const pointer=answerPointer;answerPointer=null;
  const option=event.target.closest('.answer');
  if(!pointer||pointer.id!==event.pointerId||pointer.option!==option||!app.contains(option))return;
  if(Math.hypot(event.clientX-pointer.x,event.clientY-pointer.y)>16){lastAnswerTap=null;return;}
  const now=performance.now(),value=Number($('input[name="answer"]',option).value),previous=lastAnswerTap;
  if(now-lastAutoConfirmAt<500){lastAnswerTap=null;return;}
  lastAnswerTap={index:state.index,value,time:now,x:event.clientX,y:event.clientY};
  if(previous&&previous.index===state.index&&previous.value===value&&now-previous.time<=450&&Math.hypot(event.clientX-previous.x,event.clientY-previous.y)<=24){
    event.preventDefault();confirmOption(option);
  }
});
// Listen on the visible option surface, not the hidden radio's forwarded click.
document.addEventListener('dblclick',event=>{
  const option=event.target.closest('.answer');
  if(!option||view!=='quiz')return;
  event.preventDefault();confirmOption(option);
});

// Consume the tail of a rapid triple tap before it can select the following question.
document.addEventListener('click',event=>{if(view==='quiz'&&event.target.closest('.answer')&&performance.now()-lastAutoConfirmAt<500){event.preventDefault();event.stopImmediatePropagation();}},true);
document.addEventListener('click',event=>{
  if(!event.target.closest('.answer'))lastAnswerTap=null;
  const close=event.target.closest('[data-close]');if(close){document.getElementById(close.dataset.close)?.close();return;}const control=event.target.closest('[data-action]');if(!control)return;switch(control.dataset.action){case 'sound':setSoundMuted(!isSoundMuted());control.outerHTML=soundButton();$('.sound-button').focus({preventScroll:true});break;case 'home':navigate('home');break;case 'begin':begin();break;case 'about':showAbout();break;case 'previous':if(state.index>0){state.index--;persist();renderQuestion();$('#question-title').focus({preventScroll:true});}else navigate('home');break;case 'next':advanceQuestion();break;case 'share':openShare();break;case 'read-report':$('#report').scrollIntoView({behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'instant':'smooth'});break;case 'restart':confirmAction('再认识自己一次？','这次的作答和结果将被新的小册替换。','重新开始',reset);break;case 'clear':confirmAction('清除这份记录？','当前浏览器中的答案、结果与进入记录会被清除。','清除记录',()=>{reset();try{localStorage.removeItem(STORE);sessionStorage.removeItem(AUTH);}catch{}delete gate.dataset.verified;toast('记录已清除');});break;case 'download':downloadCard();break;case 'native-share':nativeShare();break;}});
for(const dialog of [gate,about,share,confirmDialog])dialog.addEventListener('click',event=>{if(event.target===dialog){const r=dialog.getBoundingClientRect();if(event.clientX<r.left||event.clientX>r.right||event.clientY<r.top||event.clientY>r.bottom)dialog.close();}});
window.addEventListener('popstate',()=>{view=location.hash==='#result'?'result':location.hash==='#question'?'quiz':'home';render();});

// Share artwork is composed locally; no result data is encoded into its entry URL.
async function openShare(){if(!state.finished)return;const result=getResult(),d=DOMAINS.find(d=>d.id===result.top.id);tagSelection=result.low||result.tied.length===DOMAINS.length?['保持探索','留意日常','允许变化']:[...d.tags];share.innerHTML=`<div class="dialog-head"><h2 class="dialog-title" id="share-title">我的优势卡</h2><button class="close-button" data-close="share" aria-label="关闭">×</button></div><canvas class="share-preview" id="share-canvas" aria-label="分享卡预览"></canvas><div class="share-tags">${tagSelection.map(t=>`<button type="button" data-tag="${esc(t)}" aria-pressed="true">${esc(t)}</button>`).join('')}</div><div class="share-buttons"><button class="primary" data-action="download" disabled>保存图片</button><button class="secondary" data-action="native-share" disabled>分享</button></div><p class="share-error" id="share-error" role="status"></p>`;share.showModal();$('.share-tags',share).onclick=async event=>{const button=event.target.closest('[data-tag]');if(!button)return;const on=button.getAttribute('aria-pressed')!=='true';button.setAttribute('aria-pressed',String(on));tagSelection=Array.from(share.querySelectorAll('[data-tag][aria-pressed="true"]')).map(b=>b.dataset.tag);await drawShareCard();};await drawShareCard();}
async function loadArt(){const img=new Image();img.src=new URL('./assets/animals.png',import.meta.url).href;await img.decode();return img;}
function rounded(ctx,x,y,w,h,r,fill,stroke){ctx.beginPath();ctx.roundRect(x,y,w,h,r);if(fill){ctx.fillStyle=fill;ctx.fill();}if(stroke){ctx.strokeStyle=stroke;ctx.lineWidth=2;ctx.stroke();}}
function canvasDaisy(ctx,x,y,scale=1){ctx.save();ctx.translate(x,y);ctx.scale(scale,scale);ctx.strokeStyle='#9aaa70';ctx.lineWidth=3;ctx.beginPath();ctx.moveTo(0,7);ctx.quadraticCurveTo(5,25,0,40);ctx.stroke();ctx.fillStyle='#fffaf0';ctx.strokeStyle='#8c7966';ctx.lineWidth=2;for(let i=0;i<5;i++){const a=i*Math.PI*2/5;ctx.beginPath();ctx.ellipse(Math.sin(a)*9,Math.cos(a)*9,7,9,-a,0,Math.PI*2);ctx.fill();ctx.stroke();}ctx.beginPath();ctx.fillStyle='#f2cf76';ctx.arc(0,0,6,0,Math.PI*2);ctx.fill();ctx.restore();}
async function drawShareCard(){const canvas=$('#share-canvas');if(!canvas)return;const buttons=share.querySelectorAll('.share-buttons button');buttons.forEach(b=>b.disabled=true);try{const result=getResult(),d=DOMAINS.find(d=>d.id===result.top.id);await Promise.all([document.fonts.ready,document.fonts.load('30px WenKai').catch(()=>{} )]);const image=await loadArt();canvas.width=900;canvas.height=1200;const c=canvas.getContext('2d');c.fillStyle='#fbf5e9';c.fillRect(0,0,900,1200);const noise=document.createElement('canvas');noise.width=150;noise.height=150;const nc=noise.getContext('2d'),pixels=nc.createImageData(150,150);let seed=21;for(let i=0;i<pixels.data.length;i+=4){seed=(seed*1664525+1013904223)>>>0;const n=seed%90;pixels.data[i]=120;pixels.data[i+1]=102;pixels.data[i+2]=82;pixels.data[i+3]=n<40?10:0;}nc.putImageData(pixels,0,0);c.fillStyle=c.createPattern(noise,'repeat');c.fillRect(0,0,900,1200);rounded(c,35,35,830,1130,38,'#fffaf0','#b8a58f');c.setLineDash([6,8]);rounded(c,49,49,802,1102,28,null,'#dacdb9');c.setLineDash([]);c.textBaseline='middle';c.fillStyle='#88796c';c.font='24px WenKai, sans-serif';c.textAlign='left';c.fillText('日常优势小册',77,99);c.textAlign='right';c.font='21px sans-serif';c.fillText(new Intl.DateTimeFormat('zh-CN',{timeZone:'Asia/Shanghai',year:'numeric',month:'2-digit',day:'2-digit'}).format(new Date()).replaceAll('/','.'),823,99);c.fillStyle=d.paper;c.beginPath();c.ellipse(450,375,207,171,-.06,0,Math.PI*2);c.fill();const cellW=image.naturalWidth/3,cellH=image.naturalHeight/2;c.drawImage(image,(d.animal%3)*cellW,Math.floor(d.animal/3)*cellH,cellW,cellH,220,140,460,460);canvasDaisy(c,693,286,1.1);canvasDaisy(c,218,501,.8);c.textAlign='center';c.font='26px WenKai, sans-serif';c.fillStyle='#88796c';c.fillText(result.low?'还在发现自己的路上':result.tied.length>1?'我的优势，有不止一种模样':'藏在小事里的这一面',450,628);c.fillStyle='#65564d';c.font='67px WenKai, sans-serif';const title=result.low?'继续探索的你':result.tied.length===DOMAINS.length?'有许多面的你':d.companion;c.fillText(title,450,700);const line=result.low?'从一件小事开始，慢慢认识自己':result.tied.length===DOMAINS.length?'每个方向，都可以再走近一点':d.title;c.font='35px WenKai, sans-serif';if(c.measureText(line).width>700){const middle=Math.ceil(line.length/2);c.fillText(line.slice(0,middle),450,783);c.fillText(line.slice(middle),450,832);}else c.fillText(line,450,805);rounded(c,300,860,300,8,4,d.color);c.font='25px WenKai, sans-serif';const widths=tagSelection.map(t=>c.measureText(t).width+38);const total=widths.reduce((a,b)=>a+b,0)+Math.max(0,tagSelection.length-1)*16;let x=(900-total)/2;tagSelection.forEach((t,i)=>{rounded(c,x,909,widths[i],49,12,'#f0eadf');c.fillStyle='#65564d';c.fillText(t,x+widths[i]/2,934);x+=widths[i]+16;});c.strokeStyle='#d0bfa8';c.setLineDash([5,7]);c.beginPath();c.moveTo(85,1001);c.lineTo(815,1001);c.stroke();c.setLineDash([]);c.textAlign='left';c.fillStyle='#65564d';c.font='26px WenKai, sans-serif';c.fillText('我的优势，藏在哪些小事里？',87,1049);c.font='21px WenKai, sans-serif';c.fillStyle='#8a7865';c.fillText('日常行为自评 · 24 题',87,1100);const qr=new Image();qr.src=new URL('./assets/entry-qr.svg',import.meta.url).href;await qr.decode();c.drawImage(qr,702,1024,112,112);shareBlob=await new Promise(resolve=>canvas.toBlob(resolve,'image/png'));if(!shareBlob)throw new Error('image');buttons.forEach(b=>b.disabled=false);$('#share-error').textContent='';}catch{$('#share-error').textContent='图片暂时无法生成，可以直接截取结果卡。';}}
function downloadCard(){if(!shareBlob)return;if(shareUrl)URL.revokeObjectURL(shareUrl);shareUrl=URL.createObjectURL(shareBlob);const a=document.createElement('a');a.href=shareUrl;a.download='我的日常优势卡.png';document.body.append(a);a.click();a.remove();toast('图片已生成');}
async function nativeShare(){if(!shareBlob)return;const file=new File([shareBlob],'我的日常优势卡.png',{type:'image/png'});try{if(navigator.canShare?.({files:[file]})){await navigator.share({files:[file],title:'我的优势，藏在哪些小事里？'});}else downloadCard();}catch(error){if(error.name!=='AbortError')toast('暂时无法分享，可以保存图片');}}
